export const AEO_PAPER2_AGRI: PYQQuestion[] = [

  // ── AGRONOMY & CROP PRODUCTION (30 Qs) ──
  { id:"aeop2_001", year:2024, subject:"agronomy", question:"The scientific name of Rice (Paddy) is:", options:["Zea mays", "Sorghum bicolor", "Oryza sativa", "Triticum aestivum"], correct: 2, explanation:"Oryza sativa is the scientific name of Asian cultivated rice. It belongs to family Gramineae (Poaceae). O. glaberrima is African rice. Rice is the world's most important food crop by calories consumed." },
  { id:"aeop2_002", year:2024, subject:"agronomy", question:"Kharif crops are sown during:", options:["December–January", "February–March", "June–July (onset of SW monsoon)", "October–November"], correct: 2, explanation:"Kharif crops are sown at the onset of southwest monsoon in June–July and harvested after monsoon in September–October. Major kharif crops: rice, cotton, groundnut, maize, soybean." },
  { id:"aeop2_003", year:2024, subject:"agronomy", question:"The recommended N:P:K dose for high-yielding irrigated rice in Telangana is:", options:["120:60:40", "80:40:20", "60:30:30", "40:20:0"], correct: 0, explanation:"Recommended NPK for HYV paddy in Telangana: 120 kg N : 60 kg P2O5 : 40 kg K2O per hectare, applied in splits (N in 3 doses at basal, AT, PI; P and K as basal)." },
  { id:"aeop2_004", year:2024, subject:"agronomy", question:"'System of Rice Intensification' (SRI) was developed in:", options:["India", "Madagascar", "Japan", "Philippines"], correct: 1, explanation:"SRI was developed by Fr. Henri de Laulanié in Madagascar in the 1980s. Key principles: young seedlings (8–12 days), single seedling, wide spacing (25×25cm), intermittent irrigation, and compost." },
  { id:"aeop2_005", year:2024, subject:"agronomy", question:"'Drip irrigation' compared to flood irrigation has water use efficiency of:", options:["60–70%", "50–60%", "40–50%", "80–95%"], correct: 3, explanation:"Drip irrigation achieves 80–95% water use efficiency by delivering water directly to the root zone, minimising evaporation and runoff. Flood irrigation is only 30–40% efficient." },
  { id:"aeop2_006", year:2024, subject:"agronomy", question:"'Land Equivalent Ratio' (LER) > 1.0 in intercropping means:", options:["LER has no significance", "Crops compete and reduce total yield", "Intercropping is inferior to sole cropping", "Intercropping is more productive than sole cropping per unit area"], correct: 3, explanation:"LER > 1.0 means intercropping system is more productive than sole crops per unit area. LER = 1.5 means 1.5 ha of sole crops needed to equal 1 ha of intercrop — 50% more land-efficient." },
  { id:"aeop2_007", year:2024, subject:"agronomy", question:"Nitrogen fixation by Rhizobium in legumes is approximately:", options:["500 kg N/ha", "50–300 kg N/ha", "20–50 kg N/ha", "5–10 kg N/ha"], correct: 1, explanation:"Rhizobium in legume root nodules fixes 50–300 kg N/ha/season depending on the crop, host-bacteria compatibility, and soil conditions. Soybean: 100–200 kg, groundnut: 50–150 kg N/ha." },
  { id:"aeop2_008", year:2024, subject:"agronomy", question:"'Stubble mulching' conserves soil moisture by:", options:["Composting residues first", "Burning residues", "Ploughing residues deep", "Keeping crop residues on soil surface to reduce evaporation"], correct: 3, explanation:"Stubble mulching retains crop residues on the soil surface, creating a mulch layer that reduces evaporation, moderates temperature, suppresses weeds, and gradually adds organic matter." },
  { id:"aeop2_009", year:2024, subject:"agronomy", question:"The critical stage of water requirement in wheat is:", options:["Crown root initiation (20–25 DAS)", "Maturity stage", "Germination only", "Tillering stage"], correct: 0, explanation:"Crown root initiation (20–25 DAS) is the most critical stage for water in wheat. Missing irrigation at this stage causes maximum yield loss as root establishment is critical." },
  { id:"aeop2_010", year:2024, subject:"agronomy", question:"'Zero tillage' helps primarily in:", options:["Increasing soil pH", "Conserving soil moisture, reducing erosion, and saving fuel/labour costs", "Increasing weed pressure", "Improving seed germination"], correct: 1, explanation:"Zero tillage conserves moisture by reducing soil disturbance, minimises erosion, saves fuel and labour (25–40% cost reduction), and maintains soil organic carbon and earthworm populations." },
  { id:"aeop2_011", year:2024, subject:"agronomy", question:"Sugarcane is commercially propagated by:", options:["Root cuttings", "Layering", "Seeds", "Stem cuttings called 'setts' (2–3 budded pieces)"], correct: 3, explanation:"Sugarcane is vegetatively propagated using stem setts (2–3 node pieces). Seeds are used only in breeding. Sett treatment with fungicide and rapid ratoon stunting (RRS) detection is important." },
  { id:"aeop2_012", year:2024, subject:"agronomy", question:"'Nipping' in pigeonpea (redgram) at 30–40 DAS is done to:", options:["Remove apical tip to break apical dominance, increase branching and yield", "Apply pesticides", "Thin out plants", "Increase plant height"], correct: 0, explanation:"Nipping removes the terminal growing point, suppressing apical dominance, promoting lateral branches, more flowering shoots, and ultimately higher pod numbers and yield." },
  { id:"aeop2_013", year:2024, subject:"agronomy", question:"'Broad Bed and Furrow' (BBF) planting system is recommended for:", options:["Heavy black cotton soils in high-rainfall areas for improved drainage", "Acidic red soils", "Sandy desert soils", "Paddy cultivation in lowlands"], correct: 0, explanation:"BBF creates raised beds with furrows for drainage, recommended for black cotton soils (Vertisols) of Telangana and Maharashtra where waterlogging during heavy rains damages crops like soybean and chickpea." },
  { id:"aeop2_014", year:2024, subject:"agronomy", question:"'Crop rotation' helps break:", options:["Soil organic matter", "Pest and disease cycles — pathogens starve without host crop", "Soil hardpan", "Weed seeds only"], correct: 1, explanation:"Crop rotation disrupts pest, disease, and weed cycles. Host-specific pathogens and insects decline when non-host crops are grown in the next season, reducing pesticide needs." },
  { id:"aeop2_015", year:2024, subject:"agronomy", question:"Photoperiod-sensitive crops flower in response to:", options:["Temperature only", "Soil nutrients", "Rainfall amount", "Relative length of day and night (photoperiod)"], correct: 3, explanation:"Photoperiodism is the response of plants to relative day/night length. Short-day plants (rice, soybean) flower when days are short; long-day plants (wheat) flower when days are long." },
  { id:"aeop2_016", year:2024, subject:"agronomy", question:"'Integrated Farming System' (IFS) integrates:", options:["Contract farming only", "Crops + livestock + fishery + horticulture on the same farm for resource recycling", "Only crop production", "Only organic farming methods"], correct: 1, explanation:"IFS integrates multiple enterprises (crops, livestock, fishery, poultry, horticulture, agroforestry) on the same farm. This diversifies income, recycles farm resources, and reduces risk." },
  { id:"aeop2_017", year:2024, subject:"agronomy", question:"'Fertigation' means applying fertilizers through:", options:["Deep placement with a plough", "Broadcasting on soil", "Drip or sprinkler irrigation system", "Foliar spray by hand"], correct: 2, explanation:"Fertigation delivers water-soluble fertilizers through drip/sprinkler systems directly to the root zone, improving fertilizer use efficiency by 20–30% compared to soil broadcasting." },
  { id:"aeop2_018", year:2024, subject:"agronomy", question:"Cotton belongs to the family:", options:["Solanaceae", "Gramineae", "Malvaceae", "Leguminosae"], correct: 2, explanation:"Cotton (Gossypium spp.) belongs to family Malvaceae. In Telangana, Bt cotton (Gossypium hirsutum × G. barbadense hybrid) is predominantly grown in northern districts (Adilabad, Nizamabad)." },
  { id:"aeop2_019", year:2024, subject:"agronomy", question:"'Alternate Wetting and Drying' (AWD) in rice saves approximately:", options:["60% water", "15–30% water without significant yield loss", "5%", "50% water"], correct: 1, explanation:"AWD allows soil to dry to 15–20 cm below surface between irrigations. It saves 15–30% water vs. continuous flooding while maintaining near-equal yield — promoting water-efficient paddy cultivation." },
  { id:"aeop2_020", year:2024, subject:"agronomy", question:"'Harvest Index' of modern HYV wheat is approximately:", options:["15–20%", "25–30%", "40–50%", "60–70%"], correct: 2, explanation:"Harvest Index = (economic yield)/(total above-ground dry matter) × 100. Modern HYV wheat HI is 40–50% vs 25–30% for traditional varieties, reflecting improved grain-filling efficiency." },
  { id:"aeop2_021", year:2024, subject:"agronomy", question:"'Green manure' crop Sesbania (Dhaincha) can fix approximately:", options:["5 kg N/ha", "50–100 kg N/ha", "200 kg N/ha", "20–30 kg N/ha"], correct: 1, explanation:"Sesbania aculeata (Dhaincha) is one of the best green manure crops, fixing 50–100 kg N/ha through root nodules when incorporated at 40–45 days. It also adds significant organic matter." },
  { id:"aeop2_022", year:2024, subject:"agronomy", question:"'Seed rate' for direct seeded rice (DSR) is:", options:["5–8 kg/ha", "40–50 kg/ha", "80–100 kg/ha", "25–30 kg/ha"], correct: 1, explanation:"DSR (direct-seeded rice) requires 40–50 kg/ha seed rate for adequate plant population. Transplanted rice needs only 25–30 kg/ha for nursery. DSR saves labour and water." },
  { id:"aeop2_023", year:2024, subject:"agronomy", question:"'Soil solarisation' is effective because:", options:["It increases soil pH", "It adds nutrients to soil", "It improves soil structure", "High temperature (45–55°C at 10 cm) under transparent plastic kills pathogens, nematodes, and weed seeds"], correct: 3, explanation:"Soil solarisation (covering moist soil with transparent PE plastic in summer for 4–6 weeks) raises soil temperature to lethal levels, killing soil-borne pathogens, root-knot nematodes, and annual weed seeds." },
  { id:"aeop2_024", year:2024, subject:"agronomy", question:"'Cropping intensity' of 150% means:", options:["50% irrigated area", "150 crops per year", "Crops grown on 1.5 times the net sown area (double cropping on 50% of land)", "150 kg seed/ha"], correct: 2, explanation:"Cropping intensity = (Total cropped area/Net sown area) × 100. 150% means on average, each unit of land is cropped 1.5 times per year — some land grows 2 crops, rest grows 1 crop." },
  { id:"aeop2_025", year:2024, subject:"agronomy", question:"Major 'kharif pulses' grown in Telangana are:", options:["Cowpea only", "Bengal gram and lentil", "Pigeonpea (redgram) and black gram", "Peas only"], correct: 2, explanation:"Major kharif pulses in Telangana: Pigeonpea (Cajanus cajan/redgram — 5–6 lakh ha) and Black gram (Vigna mungo/urad — 3–4 lakh ha). Bengal gram is a rabi pulse." },
  { id:"aeop2_026", year:2024, subject:"agronomy", question:"'FLD' (Front Line Demonstration) is conducted on:", options:["KVK training centres", "Farmers' own fields with their resources for showing new technology performance", "Research station fields", "Government demonstration farms"], correct: 1, explanation:"FLDs are conducted on farmers' fields (not research stations) using farmer's land and labour, with KVK/ICAR backstopping. This validates real farm performance and builds credibility for technology." },
  { id:"aeop2_027", year:2024, subject:"agronomy", question:"'Weed index' is defined as the percentage reduction in crop yield due to:", options:["Pest damage", "Weed competition", "Drought", "Disease damage"], correct: 1, explanation:"Weed Index (WI) = [(Weed-free yield − Weedy yield) / Weed-free yield] × 100. Higher WI = more serious weed problem. WI of cotton is typically 30–50% without weed management." },
  { id:"aeop2_028", year:2024, subject:"agronomy", question:"'Azolla-Anabaena' symbiosis in paddy fields fixes approximately:", options:["2–5 kg N/ha/season", "20–150 kg N/ha/season", "Only phosphorus", "500 kg N/ha/season"], correct: 1, explanation:"Azolla (water fern) hosts Anabaena azollae (cyanobacterium) which fixes 20–150 kg N/ha/season. When grown as green manure before transplanting, it significantly reduces chemical N fertilizer needs." },
  { id:"aeop2_029", year:2024, subject:"agronomy", question:"'Ratooning' in sugarcane means:", options:["Planting fresh setts each year", "Allowing new shoots (ratoons) to grow from stubble after main crop harvest", "Harvesting cane twice in same season", "Changing sugarcane variety"], correct: 1, explanation:"Ratoon crop grows from the stubble (base of stems) left after harvesting the plant crop. It saves input costs (30–40% less) as no fresh planting is needed. Good ratoon management is essential." },
  { id:"aeop2_030", year:2024, subject:"agronomy", question:"National average paddy yield in India is approximately:", options:["6 t/ha", "2.6 t/ha", "1.5 t/ha", "4.5 t/ha"], correct: 1, explanation:"India's national average paddy yield is approximately 2.6 t/ha (2,600 kg/ha). Punjab achieves ~4.5 t/ha (highest), while potential yield with best varieties and management can reach 8–10 t/ha." },

  // ── SOIL SCIENCE & FERTILIZERS (25 Qs) ──
  { id:"aeop2_031", year:2024, subject:"soil-science", question:"The optimal pH range for most agricultural crops is:", options:["3.0–4.5", "4.0–5.5", "5.5–7.5", "7.5–9.0"], correct: 2, explanation:"Most crops grow best between pH 5.5–7.5. Below 5.5, Al and Mn toxicity and P unavailability limit growth. Above 7.5, Fe, Zn, Mn become insoluble and unavailable." },
  { id:"aeop2_032", year:2024, subject:"soil-science", question:"Nitrogen content in Urea fertilizer is:", options:["46%", "21%", "26%", "32%"], correct: 0, explanation:"Urea [CO(NH2)2] contains 46% N — the highest among solid nitrogen fertilizers. It is India's most widely used nitrogenous fertilizer due to its high analysis and good crop response." },
  { id:"aeop2_033", year:2024, subject:"soil-science", question:"Black cotton soils (Vertisols) swell when wet because they contain:", options:["Montmorillonite (smectite) 2:1 expanding clay", "Kaolinite clay", "Halloysite clay", "Illite clay"], correct: 0, explanation:"Montmorillonite clay has a 2:1 expanding lattice structure that absorbs water molecules between layers, causing 30–100% volume expansion when wet and deep shrinkage cracks on drying." },
  { id:"aeop2_034", year:2024, subject:"soil-science", question:"Gypsum (CaSO4·2H2O) is used for reclaiming:", options:["Waterlogged soils", "Acidic soils", "Saline soils", "Sodic (alkali) soils with high ESP"], correct: 3, explanation:"Gypsum supplies Ca2+ that replaces Na+ from exchange sites in sodic soils. The displaced Na+ is then leached with irrigation water, reducing ESP and restoring soil structure." },
  { id:"aeop2_035", year:2024, subject:"soil-science", question:"'Khaira disease' of paddy is caused by deficiency of:", options:["Zinc", "Boron", "Iron", "Manganese"], correct: 0, explanation:"Khaira disease (paddy) is caused by Zinc deficiency. Symptoms appear 2–4 weeks after transplanting: pale yellow-brown leaf spots, stunting, poor tillering. Corrected by ZnSO4 at 25 kg/ha." },
  { id:"aeop2_036", year:2024, subject:"soil-science", question:"DAP (Di-Ammonium Phosphate) contains:", options:["16% N + 36% P2O5", "18% N + 46% P2O5", "46% N + 18% P2O5", "20% N + 20% P2O5"], correct: 1, explanation:"DAP [(NH4)2HPO4] contains 18% N + 46% P2O5. It is the most widely used phosphatic fertilizer in India, providing both N and P in a single application." },
  { id:"aeop2_037", year:2024, subject:"soil-science", question:"'Soil Organic Carbon' (SOC) in Telangana's red soils is generally:", options:["Very high (>5%)", "High (>3%)", "Low (<0.5%)", "Medium (1–2%)"], correct: 2, explanation:"Telangana's red alfisols characteristically have low organic carbon (<0.5%, often 0.2–0.4%) due to high temperature accelerating decomposition, low biomass return, and burning of crop residues." },
  { id:"aeop2_038", year:2024, subject:"soil-science", question:"'Nitrification' in soil is the process of converting:", options:["N2 gas to NH4+", "Organic N to NH4+", "NH4+ to NO3- by Nitrosomonas and Nitrobacter bacteria", "NO3- to N2 gas"], correct: 2, explanation:"Nitrification: NH4+ → NO2- (by Nitrosomonas) → NO3- (by Nitrobacter). It is an aerobic process. The resulting nitrate is plant-available but can be leached or lost through denitrification." },
  { id:"aeop2_039", year:2024, subject:"soil-science", question:"'Vermicompost' NPK content is approximately:", options:["N:0.5%, P:0.1%, K:0.1%", "N:46%, P:0%, K:0%", "N:5%, P:4%, K:4%", "N:1.5–2%, P:0.75–1.5%, K:1–1.5%"], correct: 3, explanation:"Vermicompost (earthworm compost) contains N: 1.5–2.0%, P: 0.75–1.5%, K: 1.0–1.5%, plus micronutrients and beneficial microorganisms — far superior to regular FYM (N:0.5%)." },
  { id:"aeop2_040", year:2024, subject:"soil-science", question:"Phosphorus movement in soil is mainly through:", options:["Diffusion (very short range, 0.1–1 cm)", "Mass flow with irrigation water", "Root exudate absorption", "Interception only"], correct: 0, explanation:"Phosphorus moves to roots mainly by diffusion over very short distances (0.1–1 cm) — much slower than N (mass flow) or K (both). This is why band placement near roots improves P uptake efficiency." },
  { id:"aeop2_041", year:2024, subject:"soil-science", question:"'Denitrification' is the process where:", options:["Organic N is mineralised to NH4+", "Ammonium is converted to nitrate", "Nitrate is converted to N2 and N2O gases by anaerobic bacteria", "Nitrogen gas is fixed into soil"], correct: 2, explanation:"Denitrification converts soil nitrate (NO3-) to gaseous N2O and N2 under anaerobic conditions (waterlogged soils) by bacteria like Pseudomonas and Paracoccus. Major N loss in flooded rice fields." },
  { id:"aeop2_042", year:2024, subject:"soil-science", question:"The recommended dose of ZnSO4 for paddy as soil application is:", options:["25 kg/ha", "50 kg/ha", "5 kg/ha", "12.5 kg/ha"], correct: 0, explanation:"ZnSO4 (zinc sulphate, 21% Zn) is applied at 25 kg/ha as basal dose for paddy. For correcting deficiency in standing crop, 0.5% ZnSO4 foliar spray (2 applications) is recommended." },
  { id:"aeop2_043", year:2024, subject:"soil-science", question:"'Single Super Phosphate' (SSP) contains:", options:["16% P2O5 + 12% S", "26% P2O5", "46% P2O5", "32% P2O5"], correct: 0, explanation:"SSP contains 16% P2O5 (water-soluble) + 12% S (as CaSO4). Despite low P content, its sulphur content makes it valuable for oilseed and pulse crops, which have high sulphur requirements." },
  { id:"aeop2_044", year:2024, subject:"soil-science", question:"'Base saturation' of soil refers to percentage of CEC occupied by:", options:["Basic cations — Ca2+, Mg2+, K+, Na+", "Total nutrients", "H+ and Al3+ ions", "Only Ca2+"], correct: 0, explanation:"Base saturation = (Sum of exchangeable basic cations / CEC) × 100. Fertile neutral soils have >80% base saturation. Acid soils have low base saturation with H+ and Al3+ dominating." },
  { id:"aeop2_045", year:2024, subject:"soil-science", question:"'Soil Health Card' is issued to farmers every:", options:["1 year", "5 years", "2 years", "3 years"], correct: 2, explanation:"Soil Health Cards are issued every 2 years (every two crop seasons) based on soil sample collection and analysis from all surveyed plots, providing updated crop-wise fertilizer recommendations." },
  { id:"aeop2_046", year:2024, subject:"soil-science", question:"'Neem-coated Urea' (NCU) improves efficiency by:", options:["Increasing N content", "Acting as a pesticide only", "Slow-releasing N — neem's nitrification inhibitors delay NH4+ to NO3- conversion, reducing N losses", "Decreasing N content"], correct: 2, explanation:"Neem oil coating inhibits Nitrosomonas activity (nitrification), keeping N as ammonium (NH4+) longer in soil, reducing leaching and denitrification losses, improving NUE by 10–15%." },
  { id:"aeop2_047", year:2024, subject:"soil-science", question:"Soil texture is determined by the relative percentages of:", options:["Humus, sand, and clay", "pH, EC, and bulk density", "Gravel, sand, and organic matter", "Sand, silt, and clay"], correct: 3, explanation:"Soil texture is the relative proportion of sand (0.05–2mm), silt (0.002–0.05mm), and clay (<0.002mm). Texture is permanent — determines water retention, drainage, workability, and nutrient-holding capacity." },
  { id:"aeop2_048", year:2024, subject:"soil-science", question:"'PSB' (Phosphate Solubilising Bacteria) converts:", options:["Organic matter to humus", "Atmospheric N2 to NH4+", "Nitrate to nitrogen gas", "Insoluble soil phosphates to soluble plant-available forms"], correct: 3, explanation:"PSB (Bacillus subtilis, Pseudomonas fluorescens, Aspergillus niger) produces organic acids and phosphatase enzymes that convert insoluble Ca-P, Fe-P, and Al-P to soluble orthophosphate for plant uptake." },
  { id:"aeop2_049", year:2024, subject:"soil-science", question:"Saline soils have ECe (electrical conductivity of saturation extract) greater than:", options:["4 dS/m", "8 dS/m", "2 dS/m", "1 dS/m"], correct: 0, explanation:"Saline soils are defined as ECe > 4 dS/m, pH < 8.5, and ESP < 15%. High soluble salts cause osmotic stress in plants. Reclamation requires leaching with good-quality water." },
  { id:"aeop2_050", year:2024, subject:"soil-science", question:"'Soil organic matter' improves all of the following EXCEPT:", options:["Soil structure and aggregation", "Water retention", "Soil bulk density (it decreases bulk density)", "Nutrient availability"], correct: 2, explanation:"Soil organic matter improves water retention, structure, CEC, microbial activity, and nutrient supply. It DECREASES bulk density (improves porosity) — so bulk density is not 'improved' by increasing it." },
  { id:"aeop2_051", year:2024, subject:"soil-science", question:"'Potassium deficiency' in plants shows as:", options:["Purple discolouration of leaves", "Yellowing of youngest leaves", "Marginal leaf scorch (necrosis) starting from older leaves", "Interveinal chlorosis of young leaves"], correct: 2, explanation:"K is phloem-mobile; deficiency shows first on older leaves as marginal and tip scorch/necrosis since K is remobilised from old to young growing tissues. Common in sandy soils and with heavy N application." },
  { id:"aeop2_052", year:2024, subject:"soil-science", question:"'Boron' deficiency in crops causes:", options:["Yellowing of old leaves", "Root rot", "Death of growing points, hollow stem in cauliflower, heart rot in beet", "Interveinal chlorosis"], correct: 2, explanation:"Boron is essential for cell wall synthesis, pollen viability, and reproductive growth. Deficiency kills apical meristems and growing points, causes hollow stem in cauliflower and brassicas, heart rot in sugar beet." },
  { id:"aeop2_053", year:2024, subject:"soil-science", question:"'Rhizobium' biofertilizer is used for:", options:["Non-leguminous crops", "All vegetable crops", "Leguminous crops (groundnut, soybean, chickpea, pigeonpea)", "Fruit crops only"], correct: 2, explanation:"Rhizobium forms N2-fixing symbiotic nodules in legume roots. Different species are crop-specific: Bradyrhizobium japonicum for soybean, Rhizobium leguminosarum for chickpea, R. japonicum for groundnut." },
  { id:"aeop2_054", year:2024, subject:"soil-science", question:"'C:N ratio' of well-matured compost is approximately:", options:["100:1", "50:1", "5:1", "20:1"], correct: 3, explanation:"Well-decomposed compost has C:N ratio of ~20:1. Fresh organic matter has C:N >100:1. Soil microbes prefer C:N ~25:1. Below 20:1, N is released (mineralisation); above 30:1, N is immobilised." },
  { id:"aeop2_055", year:2024, subject:"soil-science", question:"'Sulphur deficiency' symptoms in oilseed crops appear as:", options:["Brown water-soaked spots", "Yellowing of old leaves first", "Marginal leaf scorch", "Uniform yellowing of young (newest) leaves — similar to N but affects young leaves first"], correct: 3, explanation:"Sulphur is relatively immobile in plants. Deficiency symptoms appear first on young leaves as pale yellow colouring of the entire leaf blade — distinguishing it from N deficiency (old leaves yellow first)." },

  // ── ENTOMOLOGY & PEST MANAGEMENT (20 Qs) ──
  { id:"aeop2_056", year:2024, subject:"entomology", question:"Brown Plant Hopper (BPH) of rice causes:", options:["Dead heart symptom", "Leaf folding", "Hopperburn — patches of dead brown plants from phloem sap sucking at base of tillers", "Silver shoot symptom"], correct: 2, explanation:"BPH (Nilaparvata lugens) causes hopperburn — irregular patches of wilted, straw-coloured plants from its concentrated feeding at the tiller base. Heavy infestations can destroy entire paddy fields." },
  { id:"aeop2_057", year:2024, subject:"entomology", question:"'Yellow Stem Borer' of rice is:", options:["Sesamia inferens", "Chilo suppressalis", "Busseola fusca", "Scirpophaga incertulas"], correct: 3, explanation:"Scirpophaga incertulas (Lepidoptera: Crambidae) is the yellow stem borer — the most damaging rice stem borer in India. Causes deadheart (vegetative) and whitehead (reproductive) symptoms." },
  { id:"aeop2_058", year:2024, subject:"entomology", question:"'Economic Threshold Level' (ETL) is the pest density at which:", options:["Zero tolerance is required", "Control action must be taken to prevent pest reaching Economic Injury Level", "All crops are destroyed", "Biological control is released"], correct: 1, explanation:"ETL is the pest population density at which management action (spraying etc.) must be initiated to prevent the population from reaching EIL (where economic damage occurs). It is slightly below EIL." },
  { id:"aeop2_059", year:2024, subject:"entomology", question:"'Trichogramma' sp. is an egg parasitoid of:", options:["Sucking pests (aphids, whiteflies)", "Stored grain pests", "Lepidopteran pests (caterpillars) — parasitises eggs before hatching", "Soil insects"], correct: 2, explanation:"Trichogramma chilonis and T. japonicum parasitise eggs of lepidopteran pests including Helicoverpa armigera, Spodoptera, and stem borers. Mass-reared and released at 50,000/acre as biocontrol agents." },
  { id:"aeop2_060", year:2024, subject:"entomology", question:"Neonicotinoid insecticide 'Imidacloprid' acts by:", options:["Inhibiting acetylcholinesterase", "Inhibiting chitin synthesis", "Binding to nicotinic acetylcholine receptors causing continuous nerve stimulation", "Disrupting cell membrane"], correct: 2, explanation:"Imidacloprid (neonicotinoid) is an agonist of insect nicotinic acetylcholine receptors, causing irreversible receptor stimulation, paralysis, and death. Systemic — translocated in plant xylem after soil/seed treatment." },
  { id:"aeop2_061", year:2024, subject:"entomology", question:"'Helicoverpa armigera' (American bollworm) is a pest of:", options:["Only cotton", "Multiple crops — cotton, chickpea, tomato, sorghum (highly polyphagous)", "Only rice", "Only pulses"], correct: 1, explanation:"H. armigera is one of the most polyphagous agricultural pests worldwide, attacking over 180 host plants. Known as cotton bollworm, gram pod borer, tomato fruit borer — causing massive economic damage." },
  { id:"aeop2_062", year:2024, subject:"entomology", question:"'Bt (Bacillus thuringiensis)' based bioinsecticide acts against:", options:["Fungi", "All insects equally", "Lepidopteran caterpillars (Cry proteins are toxic to specific larval gut cells)", "Sucking pests only"], correct: 2, explanation:"Bt Cry proteins (crystalline toxins) are specifically toxic to Lepidoptera (and some Diptera/Coleoptera depending on Bt strain) — they bind to receptors in insect gut and cause cell lysis. Safe for mammals and beneficials." },
  { id:"aeop2_063", year:2024, subject:"entomology", question:"'Whitefly' (Bemisia tabaci) is most damaging because it:", options:["Bores into stems", "Causes soil-borne disease", "Feeds on roots", "Transmits numerous plant viruses (ToLCV, CLCuV, BYVMV) while feeding"], correct: 3, explanation:"B. tabaci transmits over 200 plant viruses including Tomato Leaf Curl Virus, Cotton Leaf Curl Virus, and Bhendi Yellow Vein Mosaic Virus. This makes it one of the most economically important insect pests." },
  { id:"aeop2_064", year:2024, subject:"entomology", question:"'Pheromone traps' in crop fields are used for:", options:["Directly killing all pests", "Monitoring adult pest population density for ETL-based decisions", "Releasing beneficial insects", "Applying pesticides"], correct: 1, explanation:"Sex pheromone traps attract and trap adult male insects using synthetic female sex pheromones. Trap catches help monitor pest population levels, determine when ETL is reached, and time insecticide applications." },
  { id:"aeop2_065", year:2024, subject:"entomology", question:"'Chrysoperla carnea' (lacewing) is a:", options:["Pest of vegetables", "Predator of aphids, thrips, whiteflies, and small caterpillars", "Parasitoid of eggs", "Pollinators only"], correct: 1, explanation:"Chrysoperla carnea (common green lacewing) is a generalist predator — both larvae (aphid lions) and adults feed on aphids, thrips, mites, whiteflies, and small caterpillars. It is mass-reared for biocontrol." },
  { id:"aeop2_066", year:2024, subject:"entomology", question:"'Dead heart' symptom in paddy at vegetative stage is caused by:", options:["Leaf folder", "Rice stem borers", "BPH", "Gall midge"], correct: 1, explanation:"Dead heart (central tiller dies, turns yellow then brown, easily pulled out) is caused by stem borer larvae (Scirpophaga incertulas — yellow stem borer) boring into the central tiller at the vegetative stage." },
  { id:"aeop2_067", year:2024, subject:"entomology", question:"'IPM' (Integrated Pest Management) combines:", options:["Cultural, biological, chemical, and mechanical methods to keep pests below economic levels", "Only biological control", "Only chemical pesticides", "Only organic methods"], correct: 0, explanation:"IPM is an ecosystem-based strategy using multiple compatible tactics: resistant varieties, crop rotation (cultural), biocontrol agents (biological), targeted pesticides at ETL (chemical), and physical traps (mechanical)." },
  { id:"aeop2_068", year:2024, subject:"entomology", question:"'Mites' belong to which class?", options:["Crustacea", "Arachnida (8 legs, 2 body parts)", "Insecta", "Myriapoda"], correct: 1, explanation:"Mites (Order Acarina) belong to Class Arachnida, not Insecta. They have 8 legs (adults), 2 body parts (cephalothorax + abdomen fused as gnathosoma + idiosoma), and no wings." },
  { id:"aeop2_069", year:2024, subject:"entomology", question:"'Chlorpyrifos' insecticide belongs to which group?", options:["Carbamate", "Organochlorine", "Organophosphate", "Pyrethroid"], correct: 2, explanation:"Chlorpyrifos is an organophosphate (OP) insecticide inhibiting acetylcholinesterase. It has broad-spectrum contact, stomach, and vapour activity against insects in soil and above-ground." },
  { id:"aeop2_070", year:2024, subject:"entomology", question:"'NPV' (Nuclear Polyhedrosis Virus) as biocontrol is specific to:", options:["Fungi and bacteria", "All insects equally", "Host-specific Lepidoptera larvae", "Only sucking pests"], correct: 2, explanation:"NPV (baculovirus) is highly host-specific — HaNPV targets only Helicoverpa armigera larvae, SpltNPV targets only Spodoptera litura larvae. Applied at 250 Larval Equivalents/ha at first sign of larval infestation." },
  { id:"aeop2_071", year:2024, subject:"entomology", question:"'Refuge crop' strategy in Bt cotton is to:", options:["Plant 20% non-Bt cotton to maintain susceptible insect population and delay Bt resistance evolution", "Produce more cotton", "Attract pest insects away", "Increase yield in border rows"], correct: 0, explanation:"Refuge strategy (IRM) requires 20% non-Bt cotton border rows so susceptible pink bollworms from refuge mate with resistant survivors from Bt cotton, keeping resistance genes recessive and delaying resistance development." },
  { id:"aeop2_072", year:2024, subject:"entomology", question:"'Silver shoot' (onion leaf) symptom in paddy is caused by:", options:["Stem borer", "Leaf folder", "Rice gall midge (Orseolia oryzae)", "BPH"], correct: 2, explanation:"Rice gall midge larvae bore into tillers and form a characteristic hollow, silver-coloured, tube-like structure ('silver shoot' or 'onion leaf' or 'trumpet shoot') from the central tiller instead of normal leaf development." },
  { id:"aeop2_073", year:2024, subject:"entomology", question:"'Botanicals' used as insecticides include:", options:["Only synthetic pyrethroids", "NSKE (Neem Seed Kernel Extract), Pyrethrum, Rotenone", "Endosulfan and DDT", "Only fungicides"], correct: 1, explanation:"Botanical insecticides are plant-derived: NSKE (Azadirachtin from neem), Pyrethrum (from Chrysanthemum cinerariaefolium), Rotenone (from derris roots), and Nicotine (from tobacco) act as antifeedants, repellents, or contact poisons." },
  { id:"aeop2_074", year:2024, subject:"entomology", question:"'Spray schedule' for cotton recommends first spray:", options:["At 45–60 DAS only when sucking pest ETL is reached", "At seedling stage (7 DAS)", "At sowing", "Always at weekly intervals"], correct: 0, explanation:"Cotton IPM recommends avoiding early prophylactic sprays that destroy natural enemies. First spray should be given at 45–60 DAS only when sucking pest ETL is reached (jassid: 3/leaf, whitefly: 6/leaf, thrips: 5/leaf)." },
  { id:"aeop2_075", year:2024, subject:"entomology", question:"'Pre-Harvest Interval' (PHI) of a pesticide means:", options:["Minimum days between last pesticide spray and harvest to allow residue to fall below MRL", "Days after germination before pest attack", "Days before sowing when pesticide is applied", "Storage period of pesticide"], correct: 0, explanation:"PHI is mandatory waiting period between last application and harvest. It allows pesticide to degrade to levels below Maximum Residue Limits (MRL), ensuring food safety and enabling compliance for exports." },

  // ── PLANT PATHOLOGY (20 Qs) ──
  { id:"aeop2_076", year:2024, subject:"plant-pathology", question:"Blast disease of rice is caused by:", options:["Rhizoctonia solani", "Xanthomonas oryzae", "Helminthosporium oryzae", "Magnaporthe oryzae"], correct: 3, explanation:"Rice blast caused by Magnaporthe oryzae (ascomycete) is the most devastating rice disease globally. Characteristic diamond/eye-shaped lesions on leaves; neck rot at heading causes maximum yield loss." },
  { id:"aeop2_077", year:2024, subject:"plant-pathology", question:"'Bordeaux Mixture' fungicide is prepared by mixing:", options:["CuSO4 + Ca(OH)2 (slaked lime)", "ZnSO4 + lime", "FeSO4 + lime", "MnSO4 + lime"], correct: 0, explanation:"Bordeaux mixture (1:1 CuSO4:Ca(OH)2 in water) is the oldest and most widely used protectant fungicide/bactericide for downy mildew, blight, canker, and many other foliar diseases." },
  { id:"aeop2_078", year:2024, subject:"plant-pathology", question:"'Late blight' of potato is caused by:", options:["Phytophthora infestans", "Alternaria solani", "Fusarium solani", "Pythium debaryanum"], correct: 0, explanation:"Phytophthora infestans (oomycete) causes late blight, the most devastating potato disease that caused the Irish Great Famine (1845–49). It thrives in cool, humid conditions with rapid spread." },
  { id:"aeop2_079", year:2024, subject:"plant-pathology", question:"'Tikka disease' affects which crop?", options:["Groundnut (Cercospora leaf spots)", "Wheat", "Rice", "Maize"], correct: 0, explanation:"Tikka disease (early and late leaf spots) of groundnut is caused by Cercospora arachidicola (early, Type-1) and Cercosporidium personatum (late, Type-2). It is the most serious fungal disease of groundnut causing 10–50% yield loss." },
  { id:"aeop2_080", year:2024, subject:"plant-pathology", question:"'Yellow Vein Mosaic' of bhendi (okra) is caused by:", options:["A bacterium", "A fungus", "A nematode", "BYVMV — begomovirus transmitted by whitefly (Bemisia tabaci)"], correct: 3, explanation:"Bhendi Yellow Vein Mosaic Virus (BYVMV, Geminiviridae) causes characteristic bright yellow vein pattern on leaves. Transmitted persistently by B. tabaci. No cure — remove infected plants, control whitefly vector." },
  { id:"aeop2_081", year:2024, subject:"plant-pathology", question:"'Bacterial blight' (BLB) of rice spreads primarily through:", options:["Seed only", "Air (wind)", "Insects", "Irrigation water carrying Xanthomonas oryzae pv. oryzae"], correct: 3, explanation:"BLB of rice (Xanthomonas oryzae pv. oryzae) spreads through irrigation water that carries the bacteria from infected to healthy fields, entering through hydathodes (water pores) on leaf margins." },
  { id:"aeop2_082", year:2024, subject:"plant-pathology", question:"'Disease triangle' concept states that disease occurs when:", options:["Rainfall exceeds 100mm", "Temperature rises above 30°C", "Susceptible host + virulent pathogen + favourable environment all occur simultaneously", "Soil pH drops below 6"], correct: 2, explanation:"Disease triangle: plant disease requires all three conditions: a susceptible host, a virulent pathogen, and a favourable environment. Removing any one factor prevents or limits disease development." },
  { id:"aeop2_083", year:2024, subject:"plant-pathology", question:"'Mancozeb' fungicide is a:", options:["Contact (protectant) dithiocarbamate fungicide", "Antibiotic fungicide", "Systemic (curative) fungicide", "Biological fungicide"], correct: 0, explanation:"Mancozeb (manganese ethylenebis-dithiocarbamate) is a broad-spectrum contact/protectant fungicide. It must be applied preventively before infection. Controls numerous fungi causing leaf spots, blights, downy mildew." },
  { id:"aeop2_084", year:2024, subject:"plant-pathology", question:"'Trichoderma harzianum' is used as biocontrol against:", options:["Insect pests", "Soil-borne fungal pathogens (wilt, damping-off, root rot)", "Viral diseases", "Nematodes only"], correct: 1, explanation:"T. harzianum/viride is an antagonistic fungus used as seed and soil treatment against Fusarium wilt, Pythium damping-off, Sclerotinia stem rot, and Rhizoctonia root rot through mycoparasitism and antibiosis." },
  { id:"aeop2_085", year:2024, subject:"plant-pathology", question:"'Seed treatment with Thiram' is primarily used to control:", options:["Foliar diseases", "Soil-borne and seed-borne diseases at germination and seedling stage (damping-off)", "Nematodes", "Viral diseases"], correct: 1, explanation:"Thiram (TMTD, organosulphur fungicide) used as seed treatment (2–3g/kg seed) protects germinating seeds from damping-off (Pythium, Rhizoctonia), smuts (Ustilago), and collar rot organisms in the soil." },
  { id:"aeop2_086", year:2024, subject:"plant-pathology", question:"'Red rot of sugarcane' is caused by:", options:["Colletotrichum falcatum", "Xanthomonas sacchari", "Fusarium moniliforme", "Ustilago scitaminea"], correct: 0, explanation:"Red rot (caused by Colletotrichum falcatum) is the most serious sugarcane disease, called 'cancer of sugarcane'. Stalk shows red internal colouration with white patches and sour smell (acetic acid)." },
  { id:"aeop2_087", year:2024, subject:"plant-pathology", question:"'Tungro disease' of rice is transmitted by:", options:["Thrips", "Brown planthopper", "Stem borer", "Green leafhopper (Nephotettix virescens)"], correct: 3, explanation:"Rice Tungro Disease (RTD) is caused by two associated viruses (RTBV + RTSV) transmitted by green leafhopper (Nephotettix virescens) in a semi-persistent manner. Management: resistant varieties and leafhopper control." },
  { id:"aeop2_088", year:2024, subject:"plant-pathology", question:"'Wilt' diseases of crops are caused by:", options:["Seed-borne viruses", "Foliar fungi", "Root-feeding nematodes only", "Vascular pathogens — Fusarium, Verticillium, Ralstonia (bacterial wilt) colonising xylem vessels"], correct: 3, explanation:"Wilt diseases result from vascular pathogens colonising xylem vessels, blocking water and nutrient flow. Fusarium oxysporum causes wilt of tomato, banana, cotton; Ralstonia solanacearum causes bacterial wilt of solanaceous crops." },
  { id:"aeop2_089", year:2024, subject:"plant-pathology", question:"'Powdery mildew' fungi are characterised by:", options:["Black sooty mould on stems", "White powdery coating on leaf surface (ectophytic mycelium of Erysiphales)", "Brown water-soaked lesions on leaves", "Root discolouration"], correct: 1, explanation:"Powdery mildew fungi (Order Erysiphales, Ascomycetes) produce white powdery mycelium and conidia on leaf surfaces as obligate ectophytic parasites. Favoured by dry conditions with high humidity." },
  { id:"aeop2_090", year:2024, subject:"plant-pathology", question:"'Systemic fungicides' can:", options:["Kill all microorganisms in soil", "Only protect plant surfaces before infection", "Penetrate plant tissues and cure established fungal infections", "Only be used as seed treatment"], correct: 2, explanation:"Systemic (curative) fungicides are absorbed and translocated in plant tissues. Examples: Propiconazole, Tebuconazole, Carbendazim. They can cure early infections unlike contact fungicides (Mancozeb, Copper) which only protect." },
  { id:"aeop2_091", year:2024, subject:"plant-pathology", question:"'Crown gall' disease agent Agrobacterium tumefaciens is important in biotechnology because:", options:["It fixes nitrogen", "It controls nematodes", "It produces antibiotics", "Its Ti plasmid is used as a vector for plant genetic transformation"], correct: 3, explanation:"Agrobacterium's Ti plasmid (T-DNA portion) integrates into plant genome and is widely used as a vehicle for delivering desired foreign genes into dicotyledonous plants in plant biotechnology." },
  { id:"aeop2_092", year:2024, subject:"plant-pathology", question:"'Damping-off' of vegetable seedlings is primarily caused by:", options:["Alternaria spp.", "Fusarium oxysporum", "Botrytis cinerea", "Pythium spp. and Rhizoctonia solani"], correct: 3, explanation:"Damping-off (pre-emergence and post-emergence seedling collapse) is primarily caused by Pythium aphanidermatum, P. debaryanum, and Rhizoctonia solani under wet, humid nursery conditions. Managed by seed treatment and Trichoderma." },
  { id:"aeop2_093", year:2024, subject:"plant-pathology", question:"'Charcoal rot' of sorghum/soybean is most severe during:", options:["Winter season", "Nursery stage only", "Rainy season with excess moisture", "Drought and high temperature stress conditions"], correct: 3, explanation:"Charcoal rot (Macrophomina phaseolina) is a hot, dry-weather disease. Water stress at grain filling stage predisposes crops to infection. The pathogen produces abundant black microsclerotia (charcoal-like appearance)." },
  { id:"aeop2_094", year:2024, subject:"plant-pathology", question:"'Integrated Disease Management' (IDM) combines:", options:["Only biological control", "Only organic treatments", "Resistant varieties + cultural practices + biocontrol (Trichoderma, Pseudomonas) + targeted fungicide use", "Only fungicides"], correct: 2, explanation:"IDM uses a combination of: disease-resistant varieties (cheapest), cultural practices (crop rotation, balanced nutrition, proper spacing), biological agents (Trichoderma, PSF sprays), and need-based fungicide application." },
  { id:"aeop2_095", year:2024, subject:"plant-pathology", question:"'Hot water treatment' at 52°C for 30 minutes is used to manage:", options:["Post-harvest diseases only", "Seed-borne pathogens and viruses in planting material", "Soil-borne nematodes", "Fungal leaf diseases"], correct: 1, explanation:"Hot water treatment (HWT) kills seed-borne bacteria, fungi, and viruses (especially in vegetatively propagated material like sugarcane, potato) without seriously harming planting material viability." },

  // ── HORTICULTURE (20 Qs) ──
  { id:"aeop2_096", year:2024, subject:"horticulture", question:"The most popular mango variety in Telangana is:", options:["Langra", "Dasheri", "Benishan (Banganapalle)", "Alphonso"], correct: 2, explanation:"Benishan (Banganapalle) is the most popular commercial mango variety in Telangana and AP, covering ~70% of mango area. It has large yellow fruits with fibreless flesh, used for both fresh consumption and processing." },
  { id:"aeop2_097", year:2024, subject:"horticulture", question:"Banana variety 'Robusta' (Cavendish) belongs to genome group:", options:["AAB", "AB", "AAA", "AA"], correct: 2, explanation:"Robusta/Grand Naine (Cavendish types) belongs to AAA genome group — triploids derived from Musa acuminata. They are the world's most widely grown export banana varieties." },
  { id:"aeop2_098", year:2024, subject:"horticulture", question:"'Inarching' grafting method is used for which fruit crop?", options:["Grapes (hardwood cuttings)", "Mango (difficult to propagate by cuttings)", "Papaya (seeds)", "Banana (suckers)"], correct: 1, explanation:"Inarching (approach grafting) is the traditional mango propagation method where scion and rootstock remain attached to parent plants during union formation. Now being replaced by veneer/stone grafting." },
  { id:"aeop2_099", year:2024, subject:"horticulture", question:"'Alternate bearing' in mango is attributed to:", options:["Pest attack", "Soil deficiency", "Irregular rainfall", "High C:N ratio after heavy bearing year inhibiting next year's flower induction"], correct: 3, explanation:"After a heavy bearing year, carbohydrate (C) reserves are depleted, reducing the C:N ratio below 12:1 needed for flower induction, causing the 'off year'. Managing through spraying K2SO4 and paclobutrazol can regulate bearing." },
  { id:"aeop2_100", year:2024, subject:"horticulture", question:"'Tissue culture' banana plants are superior because:", options:["They are cheaper than suckers", "They are drought-tolerant", "They yield more always", "They are disease-free (BBTV-free), true-to-type, and uniformly producing"], correct: 3, explanation:"TC (tissue culture) banana plants are virus-free (especially free from Banana Bunchy Top Virus), genetically uniform, have better establishment, earlier production by 3–4 months, and higher yields than conventional suckers." },
  { id:"aeop2_101", year:2024, subject:"horticulture", question:"'Curing' of onion bulbs after harvest is done for:", options:["Applying pesticides", "Grading onions", "Increasing moisture", "Drying the neck tissue to prevent pathogen entry during storage"], correct: 3, explanation:"Curing involves spreading harvested onion bulbs for 10–14 days to dry the leaf neck (above bulb) and develop tight dry outer scales (tunic), preventing Botrytis neck rot and other storage diseases." },
  { id:"aeop2_102", year:2024, subject:"horticulture", question:"Tomato belongs to family:", options:["Leguminosae", "Malvaceae", "Solanaceae", "Cucurbitaceae"], correct: 2, explanation:"Tomato (Solanum lycopersicum, formerly Lycopersicon esculentum) belongs to Solanaceae, along with potato, brinjal, chilli, pepper, and tobacco — the nightshade family." },
  { id:"aeop2_103", year:2024, subject:"horticulture", question:"'Drip fertigation' in vegetables improves NUE (Nutrient Use Efficiency) by:", options:["100%", "20–30% compared to broadcast application", "50%", "5%"], correct: 1, explanation:"Fertigation through drip delivers nutrients directly to root zone in small frequent doses, matching crop demand, reducing leaching and volatilisation losses — improving NUE by 20–30% over broadcast application." },
  { id:"aeop2_104", year:2024, subject:"horticulture", question:"National Research Centre for Banana (NRCB) is located at:", options:["Trichy (Tiruchirappalli), Tamil Nadu", "Bengaluru", "Pune", "Hyderabad"], correct: 0, explanation:"ICAR-National Research Centre for Banana is at Tiruchirappalli (Trichy), Tamil Nadu. It is the apex institution for banana research, developing varieties, cultivation practices, and post-harvest technologies." },
  { id:"aeop2_105", year:2024, subject:"horticulture", question:"'Marigold' (Tagetes erecta) in vegetable fields is grown as:", options:["A shade crop", "A trap/companion crop to repel nematodes and some pests, and also for flower income", "A green manure crop", "A vegetable"], correct: 1, explanation:"Marigold is an effective trap/companion crop — its root exudates suppress root-knot nematodes. Planted as border rows in tomato, it also traps thrips and acts as a companion crop reducing pest pressure." },
  { id:"aeop2_106", year:2024, subject:"horticulture", question:"'Protected cultivation' (polyhouse) is mainly used for:", options:["Cotton cultivation", "High-value crops — capsicum, gerbera, carnation, tomato cherry — requiring climate control", "Sugarcane nursery", "Paddy cultivation"], correct: 1, explanation:"Protected cultivation (greenhouse/polyhouse) provides controlled environment (temperature, humidity, CO2) for growing high-value crops (capsicum, roses, gerbera) that need protection from extreme weather, pests, and diseases." },
  { id:"aeop2_107", year:2024, subject:"horticulture", question:"'Pre-harvest drop' of mango is managed by spraying:", options:["Urea at 2%", "Bordeaux mixture", "Copper fungicide", "NAA (Naphthalene Acetic Acid) at 20–40 ppm"], correct: 3, explanation:"2 sprays of NAA (20–40 ppm) at marble stage and at ripening initiation inhibit abscission zone formation, preventing premature fruit drop and improving fruit retention till harvest maturity." },
  { id:"aeop2_108", year:2024, subject:"horticulture", question:"'Papaya' is classified as:", options:["Monoecious — both flowers on same plant", "Self-pollinating hermaphrodite only", "Polygamodioecious — male, female, and hermaphrodite plants", "Dioecious — male and female plants only"], correct: 2, explanation:"Papaya is polygamodioecious — three types of plants (male/staminate, female/pistillate, hermaphrodite/bisexual) exist. Commercial cultivation prefers hermaphrodite plants (Solo types) as all produce fruit." },
  { id:"aeop2_109", year:2024, subject:"horticulture", question:"IIHR (Indian Institute of Horticultural Research) is located at:", options:["Coimbatore", "Nashik", "Hyderabad", "Hessarghatta, Bengaluru"], correct: 3, explanation:"ICAR-IIHR is at Hessarghatta, Bengaluru, Karnataka — India's premier horticultural research institute. It developed varieties like Arka Abhay (YMV-resistant okra), Arka Meghali, and many vegetable/fruit varieties." },
  { id:"aeop2_110", year:2024, subject:"horticulture", question:"Bhendi (Okra) belongs to family:", options:["Leguminosae", "Cucurbitaceae", "Solanaceae", "Malvaceae (same as cotton and hibiscus)"], correct: 3, explanation:"Bhendi/Okra (Abelmoschus esculentus) belongs to Malvaceae. It is a warm-season vegetable requiring 25–35°C for optimum growth, sensitive to frost and waterlogging." },
  { id:"aeop2_111", year:2024, subject:"horticulture", question:"'Totapuri' mango is mainly used for:", options:["Processing — pulp, pickle, chutney, juice", "Ornamental purpose", "Export to Middle East", "Fresh eating"], correct: 0, explanation:"Totapuri (Bangalora, Collector) is primarily a processing variety — used for mango pulp (export quality), pickle, chutney, and juice. Its fibreless, firm, sour-sweet flesh is ideal for industrial processing." },
  { id:"aeop2_112", year:2024, subject:"horticulture", question:"Mushroom cultivation uses:", options:["Composted/pasteurised substrates like paddy straw, sawdust, and grain", "Only water", "Only manure", "Soil as growing medium"], correct: 0, explanation:"Edible mushrooms (Agaricus bisporus — button, Pleurotus ostreatus — oyster, Volvariella volvacea — paddy straw mushroom) are grown on composted/sterilised substrates under controlled humidity and temperature." },
  { id:"aeop2_113", year:2024, subject:"horticulture", question:"'Brix value' of fruit juice measures:", options:["Total soluble solids (sugar content) by refractometer", "Vitamin C content", "Water content", "Acidity (pH)"], correct: 0, explanation:"Brix (°Bx) measures total soluble solids (mainly sugars) in fruit juice. 1°Bx = ~1g sucrose/100g solution. Used as maturity index: mango juice 18–22°Bx, grapes 18–24°Bx." },
  { id:"aeop2_114", year:2024, subject:"horticulture", question:"'Turmeric' is harvested for its:", options:["Leaves", "Underground rhizomes rich in curcumin (yellow pigment)", "Flowers", "Seeds"], correct: 1, explanation:"Turmeric (Curcuma longa) rhizomes contain curcumin (3–5%), providing yellow colour and medicinal properties. India produces ~80% of world turmeric. Nizamabad (Telangana) is famous for 'Nizamabad Bulb' variety." },
  { id:"aeop2_115", year:2024, subject:"horticulture", question:"'Cold chain' for vegetables means:", options:["Continuous refrigerated handling from farm (pre-cooling) through transport to retail, maintaining unbroken cold", "Storing in village wells", "Using ice in transport trucks only", "Selling vegetables in cold weather only"], correct: 0, explanation:"Cold chain maintains continuous temperature (near 0–10°C depending on commodity) from harvest: pre-cooling → refrigerated pack house → reefer transport → cold storage → refrigerated retail. Breaks in cold chain rapidly increase losses." },

  // ── AGRICULTURAL EXTENSION & ECONOMICS (20 Qs) ──
  { id:"aeop2_116", year:2024, subject:"extension", question:"Primary objective of Agricultural Extension is:", options:["Conduct agricultural research", "Distribute subsidies", "Collect revenue from farmers", "Help farmers help themselves — empower with knowledge and skills for self-reliant development"], correct: 3, explanation:"Extension's primary objective is to help farmers help themselves — through non-formal education and advisory services, building knowledge, skills, and confidence for sustainable agricultural development." },
  { id:"aeop2_117", year:2024, subject:"extension", question:"'Method demonstration' in extension shows:", options:["HOW to perform a skill or practice (step-by-step)", "Only financial gains", "Government schemes benefits", "WHAT results a new technology gives"], correct: 0, explanation:"Method demonstration shows the HOW — extension worker demonstrates step-by-step how to perform a practice (transplanting, pesticide mixing, vermicompost preparation). Result demonstration shows the WHAT (outcome/results)." },
  { id:"aeop2_118", year:2024, subject:"extension", question:"Everett Rogers' 'Diffusion of Innovations' (1962) identified 'Innovators' as:", options:["2.5% — venturesome, cosmopolite, risk-takers who first adopt new ideas", "Laggards (16%)", "Late Majority (34%)", "The majority of farmers"], correct: 0, explanation:"Rogers' 5 adopter categories: Innovators (2.5%), Early Adopters (13.5%), Early Majority (34%), Late Majority (34%), Laggards (16%). Innovators are first adopters — venturesome and willing to take risks." },
  { id:"aeop2_119", year:2024, subject:"extension", question:"'ATMA' (Agricultural Technology Management Agency) operates at:", options:["State level", "Block/Mandal level", "National level", "District level"], correct: 3, explanation:"ATMA is a district-level autonomous institution integrating all agricultural line departments (agriculture, horticulture, fisheries, etc.) at district level for coordinated technology transfer." },
  { id:"aeop2_120", year:2024, subject:"extension", question:"'Farmer Field School' (FFS) uses:", options:["Only radio broadcasts", "Only printed extension material", "Farmer's field as classroom for season-long experiential learning (discovery learning)", "Classroom lectures only"], correct: 2, explanation:"FFS (developed by FAO in Indonesia, 1989) uses the actual farmer's field as the classroom. Groups of 25–30 farmers conduct weekly observations/experiments during the crop season — learning by doing." },
  { id:"aeop2_121", year:2024, subject:"extension", question:"'Training and Visit' (T&V) extension system was introduced in India by:", options:["FAO", "World Bank (Daniel Benor) in 1974", "State Agriculture Departments", "ICAR"], correct: 1, explanation:"T&V system was introduced in India in 1974 through World Bank recommendation by Daniel Benor. It standardised fortnightly farm visits by Village Level Workers and monthly SMS training." },
  { id:"aeop2_122", year:2024, subject:"extension", question:"Krishi Vigyan Kendra (KVK) was first established in India at:", options:["Ludhiana", "Pondicherry (1974) under Tamil Nadu Agricultural University", "New Delhi", "Hyderabad"], correct: 1, explanation:"The first KVK was established in 1974 at Pondicherry based on ICAR recommendations. Now there are 731 KVKs across India (one per district) serving as district-level agricultural extension knowledge centres." },
  { id:"aeop2_123", year:2024, subject:"extension", question:"'Self Help Group' (SHG) in rural areas typically has:", options:["500+ members", "100–200 members", "2–5 members only", "10–20 members who save regularly and access group credit"], correct: 3, explanation:"SHGs are informal community-based groups of 10–20 members (mostly women) who save a fixed amount regularly, pool savings, and provide interest-bearing loans to members. They are the backbone of SERP/NRLM programmes." },
  { id:"aeop2_124", year:2024, subject:"extension", question:"'Minimum Support Price' (MSP) for agricultural commodities is recommended by:", options:["State Agriculture Departments", "Commission for Agricultural Costs and Prices (CACP)", "NABARD", "Food Corporation of India"], correct: 1, explanation:"CACP recommends MSP for 23 mandated crops based on: cost of production (A2+FL, C2), supply-demand balance, price trends, inter-crop price parity, and farmer welfare considerations." },
  { id:"aeop2_125", year:2024, subject:"extension", question:"'Law of Diminishing Returns' states that adding more variable input to fixed input will eventually:", options:["Have no effect on yield", "Always increase production proportionally", "Reduce marginal product of variable input (diminishing marginal returns)", "Double productivity"], correct: 2, explanation:"Law of Diminishing Marginal Returns: as more units of a variable input (fertilizer, labour) are added to a fixed input (land), the marginal (extra) product per additional unit eventually decreases." },
  { id:"aeop2_126", year:2024, subject:"extension", question:"'Break-even point' is where:", options:["Total cost equals total revenue (profit = 0)", "Maximum profit is achieved", "Fixed cost is recovered only", "Variable cost is zero"], correct: 0, explanation:"Break-even point is where Total Revenue = Total Cost, meaning TR − TC = 0 (no profit, no loss). BEP = Fixed Cost / (Price − Variable Cost per unit). Below BEP = loss; above BEP = profit." },
  { id:"aeop2_127", year:2024, subject:"extension", question:"'Farm budget' is prepared to:", options:["Plan farm activities, estimate income and expenses, and evaluate profitability of farming enterprise", "Only for tax purposes", "Show to government officials", "Apply for bank loans only"], correct: 0, explanation:"Farm budget is a written financial plan showing expected income and expenses for a farming enterprise. It helps in resource allocation, credit planning, and evaluating the economic viability of crop choices." },
  { id:"aeop2_128", year:2024, subject:"extension", question:"'Opportunity cost' in farm economics is:", options:["Transport cost of produce", "Fixed cost of machinery", "Value of the next best alternative foregone when a resource is used for one purpose", "Market price of the product"], correct: 2, explanation:"Opportunity cost is the value of the best alternative use of a resource that is foregone. E.g., the opportunity cost of using land for groundnut is the income that could have been earned from cotton on the same land." },
  { id:"aeop2_129", year:2024, subject:"extension", question:"'Price elasticity of demand' for food in India is generally:", options:["Perfectly elastic", "Inelastic (<1) — demand changes little with price", "Unitary elastic (=1)", "Highly elastic (>1)"], correct: 1, explanation:"Food is a necessity with few substitutes, so demand is inelastic (Ed < 1). A 10% price rise leads to less than 10% fall in demand. This explains why farmers suffer low prices at bumper harvest." },
  { id:"aeop2_130", year:2024, subject:"extension", question:"'Kisan Mela' is classified as which type of extension method?", options:["Mass media method", "Administrative method", "Group method (brings 50–500 farmers together for demonstrations and interaction)", "Individual method"], correct: 2, explanation:"Kisan Mela (Farmers' Fair) is a group extension method — larger than a regular group meeting but not mass media. It combines demonstrations, exhibits, competitions, input distribution, and expert interaction." },
  { id:"aeop2_131", year:2024, subject:"extension", question:"'e-NAM' (National Agricultural Market) was designed to:", options:["Import agricultural produce", "Regulate food prices", "Create unified electronic trading layer linking existing APMC mandis for transparent price discovery", "Replace all APMCs"], correct: 2, explanation:"e-NAM does NOT replace APMCs — it creates an online trading layer connecting 1,000+ existing APMC markets. Farmers, traders, and FPOs can trade through e-bidding, improving price transparency and reducing market fragmentation." },
  { id:"aeop2_132", year:2024, subject:"extension", question:"'NABARD' was established primarily to:", options:["Manage government bonds", "Control inflation", "Provide refinance to banks for agricultural and rural development lending, and support rural development", "Provide personal loans"], correct: 2, explanation:"NABARD (National Bank for Agriculture and Rural Development, 1982) provides refinance (credit) to commercial banks, RRBs, and cooperative banks for agricultural and rural lending, and supports rural development programmes." },
  { id:"aeop2_133", year:2024, subject:"extension", question:"'Disguised unemployment' in Indian agriculture means:", options:["Surplus workers in farming whose marginal productivity is near zero — removal won't reduce output", "Open unemployment", "Voluntary non-work", "Seasonal unemployment"], correct: 0, explanation:"Disguised unemployment (concealed unemployment) occurs when more workers are engaged on land than needed. The marginal product of labour approaches zero — they appear employed but contribute little to total output." },
  { id:"aeop2_134", year:2024, subject:"extension", question:"'Precision farming' uses which technologies for variable-rate input application?", options:["GPS, GIS, Remote Sensing, and Variable Rate Technology (VRT)", "Only drip irrigation", "Only soil testing", "Traditional methods only"], correct: 0, explanation:"Precision farming uses GPS (location tracking), GIS (mapping), remote sensing (satellite/drone crop monitoring via NDVI), and VRT (varying fertilizer/pesticide dose based on actual field variability) for site-specific management." },
  { id:"aeop2_135", year:2024, subject:"extension", question:"'MGNREGA' employment guarantee is a:", options:["Statutory Right under an Act of Parliament", "Government policy (not a law)", "Directive Principle only", "Fundamental Right"], correct: 0, explanation:"MGNREGA guarantees employment as a statutory right (legally enforceable under Mahatma Gandhi NREGA, 2005). Any adult rural resident can demand 100 days of work and must be provided employment within 15 days." },

  // ── ANIMAL HUSBANDRY & IRRIGATION (15 Qs) ──
  { id:"aeop2_136", year:2024, subject:"animal-husbandry", question:"'Murrah' buffalo breed is famous for:", options:["Wool production", "Highest milk yield (2,000–3,500 L/lactation) among buffalo breeds worldwide", "Draught ability", "High meat production"], correct: 1, explanation:"Murrah (from Haryana/Punjab) is the world's highest milk-yielding buffalo breed, giving 2,000–3,500 litres/lactation with 7–8% fat. It is widely exported for dairy improvement programmes." },
  { id:"aeop2_137", year:2024, subject:"animal-husbandry", question:"Normal gestation period of a cow is approximately:", options:["360 days", "280 days", "150 days", "210 days"], correct: 1, explanation:"Cow's gestation period averages 280 days (9 months 10 days). Buffalo: ~310 days. Sheep/Goat: ~150 days. Understanding gestation is important for breeding planning and farm management." },
  { id:"aeop2_138", year:2024, subject:"animal-husbandry", question:"'FMD' (Foot and Mouth Disease) vaccine in cattle is given:", options:["Every 5 years", "Once in lifetime", "Only when outbreak occurs", "Twice yearly before kharif and rabi seasons"], correct: 3, explanation:"FMD vaccination schedule: twice yearly (before each crop season) using polyvalent vaccine (Types O, A, Asia-1). Under India's national FMD control programme, vaccination covers all cattle and buffalo." },
  { id:"aeop2_139", year:2024, subject:"animal-husbandry", question:"'Sahiwal' cow is India's best indigenous dairy breed, yielding:", options:["1,500–3,500 L/lactation", "200–400 L/lactation", "500–800 L/lactation", "5,000+ L/lactation"], correct: 0, explanation:"Sahiwal (from Punjab/UP) yields 1,500–3,500 litres/lactation with 4.5% fat — India's best indigenous dairy breed. It is highly heat-tolerant, disease-resistant, and valued for tropical climate breeding." },
  { id:"aeop2_140", year:2024, subject:"animal-husbandry", question:"'Backyard poultry' rearing is recommended for rural families because:", options:["Provides egg and meat nutrition + income with minimal investment using household food waste", "Requires specialised training always", "High investment needed", "Only for commercial purpose"], correct: 0, explanation:"Backyard poultry (desi birds) requires minimal investment, uses household food waste and crop residues, provides protein (eggs and meat), generates supplemental income — particularly beneficial for women and marginal farmers." },
  { id:"aeop2_141", year:2024, subject:"irrigation", question:"'Field Capacity' of soil is the moisture content:", options:["When soil is completely dry", "After free drainage of gravitational water has ceased (held at -0.1 to -0.33 bar)", "At permanent wilting point", "Maximum water soil can hold"], correct: 1, explanation:"Field Capacity (FC) is moisture retained after gravitational water drains (1–3 days after saturation). It represents the upper limit of plant-available water storage — approximately 50% of pore space filled." },
  { id:"aeop2_142", year:2024, subject:"irrigation", question:"'Sprinkler irrigation' is most suitable for:", options:["Paddy cultivation in lowlands", "Very heavy clay soils", "Waterlogged soils only", "Uneven terrain, sandy soils, shallow-rooted crops, and moderate to low water availability"], correct: 3, explanation:"Sprinkler irrigation suits uneven topography (no levelling needed), sandy soils (rapid infiltration), shallow-rooted crops (vegetables, groundnut), and areas with limited water supply — achieving 70–80% WUE." },
  { id:"aeop2_143", year:2024, subject:"irrigation", question:"'Per Drop More Crop' component under PMKSY promotes:", options:["Flood irrigation expansion", "Free bore wells", "Only drip for horticulture", "Micro-irrigation (drip and sprinkler) with 55% subsidy for small farmers"], correct: 3, explanation:"PDMC component provides 55% subsidy for small/marginal farmers and 45% for others for installing drip or sprinkler irrigation, promoting water use efficiency and productivity improvement." },
  { id:"aeop2_144", year:2024, subject:"irrigation", question:"'Permanent Wilting Point' (PWP) of soil is approximately:", options:["15 bars", "31 bars", "0.1 bar", "0.33 bar"], correct: 0, explanation:"PWP is the soil moisture tension (~15 bars or -1.5 MPa) at which plants can no longer extract water and permanently wilt. Available water for plants = Field Capacity − Permanent Wilting Point." },
  { id:"aeop2_145", year:2024, subject:"irrigation", question:"'Micro-irrigation' systems include:", options:["Drip and sprinkler irrigation systems", "Only sprinkler irrigation", "Only flood and furrow irrigation", "Only drip irrigation"], correct: 0, explanation:"Micro-irrigation encompasses drip irrigation (emitters at root zone) and sprinkler irrigation (overhead water distribution) — both much more efficient than traditional flood/furrow irrigation methods." },

  // ── GENETICS, PLANT BREEDING & SEED TECHNOLOGY (15 Qs) ──
  { id:"aeop2_146", year:2024, subject:"genetics", question:"'Heterosis' (hybrid vigour) was coined by:", options:["Norman Borlaug", "Mendel", "Darwin", "G.H. Shull (1908)"], correct: 3, explanation:"G.H. Shull (1908) coined the term 'heterosis' to describe the superior performance of F1 hybrids over their inbred parents. This forms the basis of commercial hybrid seed production." },
  { id:"aeop2_147", year:2024, subject:"genetics", question:"Basic chromosome number of wheat (x) is:", options:["12", "7", "5", "10"], correct: 1, explanation:"Wheat has basic chromosome number x = 7. Einkorn (T. monococcum): 2n=14 (diploid), Emmer (T. dicoccum): 2n=28 (tetraploid), Bread wheat (T. aestivum): 2n=42 (hexaploid = 6×7)." },
  { id:"aeop2_148", year:2024, subject:"genetics", question:"'CMS' (Cytoplasmic Male Sterility) is used in hybrid seed production to:", options:["Increase germination rate", "Increase yield automatically", "Eliminate manual emasculation — sterile pollen makes plants female parents", "Improve resistance to diseases"], correct: 2, explanation:"CMS-based male sterile lines (A-lines) produce no viable pollen due to mitochondrial genetic factors, making them natural female parents. This eliminates costly manual emasculation in hybrid seed production." },
  { id:"aeop2_149", year:2024, subject:"genetics", question:"'Seed certification' tag colours in India: Breeder Seed tag is:", options:["Golden Yellow", "White", "Green", "Blue"], correct: 0, explanation:"Seed certification tag colours: Breeder Seed = Golden Yellow, Foundation Seed = White, Certified Seed = Blue, Truthfully Labelled = Orange. These identify seed class and ensure quality standards." },
  { id:"aeop2_150", year:2024, subject:"genetics", question:"'Colchicine' is used in plant breeding to induce:", options:["Disease resistance", "Hybrid vigour", "Mutation", "Polyploidy by inhibiting spindle formation during cell division (chromosome doubling)"], correct: 3, explanation:"Colchicine inhibits tubulin polymerisation, preventing spindle fibre formation during mitosis. This causes chromosome doubling (polyploidy) — used to create allotetraploids like Triticale and to double dihaploids." },
] as PYQQuestion[];
